insert into public.story_stats (story_id, sort_order, value_label, description) values ((select id from public.stories where event_id = (select id from public.events where slug = 'world-war-i') and locale = 'en'), 4, '4', 'empires collapsed');
insert into public.story_chapters (story_id, sort_order, title, period_label, paragraphs, figure_kind, figure_caption, shows_sides) values ((select id from public.stories where event_id = (select id from public.events where slug = 'world-war-i') and locale = 'en'), 1, 'The spark', '28 June 1914', array['In Sarajevo, a 19-year-old Bosnian Serb named Gavrilo Princip shoots Archduke Franz Ferdinand, heir to the Austro-Hungarian throne, and his wife Sophie.', 'Austria-Hungary blames Serbia. With Germany’s backing, it sends Serbia an ultimatum written to be rejected.'], 'photo', 'The Archduke and Sophie in Sarajevo, minutes before the attack', false);
insert into public.story_chapters (story_id, sort_order, title, period_label, paragraphs, figure_kind, figure_caption, shows_sides) values ((select id from public.stories where event_id = (select id from public.events where slug = 'world-war-i') and locale = 'en'), 2, 'Alliances pull everyone in', 'July – November 1914', array['Austria-Hungary declares war on Serbia on 28 July. Russia mobilizes to protect Serbia. Germany declares war on Russia on 1 August and on France on 3 August, then invades neutral Belgium to reach Paris. Britain declares war on Germany on 4 August.', 'Within a week, a Balkan crisis has become a European war. In late 1914 the Ottoman Empire joins Germany’s side and the war reaches the Middle East.'], 'map', 'Europe’s alliances, August 1914', true);
insert into public.story_chapters (story_id, sort_order, title, period_label, paragraphs, figure_kind, figure_caption, shows_sides) values ((select id from public.stories where event_id = (select id from public.events where slug = 'world-war-i') and locale = 'en'), 3, 'Trenches and stalemate', '1914 – 1916', array['France and Britain stop the German advance at the First Battle of the Marne in September 1914. Both sides dig in, and soon a line of trenches runs about 700 km from the North Sea to Switzerland.', 'Attacks across no man’s land cost huge numbers of lives for very little ground. At Verdun in 1916, French and German armies fight for about 300 days. On the first day of the Somme, 1 July 1916, the British Army suffers about 57,000 casualties, the worst day in its history.'], 'photo', 'Aerial photo of trench lines on the Somme', false);
insert into public.story_chapters (story_id, sort_order, title, period_label, paragraphs, figure_kind, figure_caption, shows_sides) values ((select id from public.stories where event_id = (select id from public.events where slug = 'world-war-i') and locale = 'en'), 4, 'A world war', '1915 – 1918', array['Fighting spreads far beyond Europe. At Gallipoli in 1915, Allied troops try to knock the Ottoman Empire out of the war and withdraw after eight months.', 'In Mesopotamia (today’s Iraq), a British-Indian army is besieged at Kut and surrenders in April 1916. In June 1916, Sharif Hussein of Mecca launches the Arab Revolt against Ottoman rule with British support. Meanwhile Britain and France secretly agree, in the Sykes–Picot Agreement, how to divide the region after the war.'], 'map', 'Fronts in the Middle East, 1915–1918', false);
insert into public.story_chapters (story_id, sort_order, title, period_label, paragraphs, figure_kind, figure_caption, shows_sides) values ((select id from public.stories where event_id = (select id from public.events where slug = 'world-war-i') and locale = 'en'), 5, '1917, the turning point', '1917 – March 1918', array['German submarines sink merchant ships without warning, and a secret German offer of an alliance to Mexico, the Zimmermann Telegram, is exposed. The United States declares war on Germany on 6 April 1917.', 'In Russia, revolution topples the tsar. The new Bolshevik government signs a separate peace with Germany at Brest-Litovsk in March 1918.'], 'photo', 'American troops arriving in France, 1917', false);
insert into public.story_chapters (story_id, sort_order, title, period_label, paragraphs, figure_kind, figure_caption, shows_sides) values ((select id from public.stories where event_id = (select id from public.events where slug = 'world-war-i') and locale = 'en'), 6, 'The end', 'March – November 1918', array['Germany moves its eastern armies west for a final Spring Offensive in March 1918 and comes close to Paris. The Allies stop it, then launch the Hundred Days Offensive on 8 August.', 'Bulgaria and the Ottoman Empire sign armistices, Austria-Hungary collapses, and Kaiser Wilhelm II abdicates. The guns fall silent at 11 a.m. on 11 November 1918.'], 'photo', 'Crowds celebrate the Armistice, 11 November 1918', false);
insert into public.story_chapters (story_id, sort_order, title, period_label, paragraphs, figure_kind, figure_caption, shows_sides) values ((select id from public.stories where event_id = (select id from public.events where slug = 'world-war-i') and locale = 'en'), 7, 'The aftermath', '1919 – 1923', array['The Treaty of Versailles is signed on 28 June 1919, five years to the day after Sarajevo. It blames Germany for the war and demands heavy reparations.', 'The German, Austro-Hungarian, Russian and Ottoman empires are gone. New states appear in Europe, and Britain and France take control of former Ottoman lands as League of Nations mandates, drawing borders that still shape the Middle East. Anger over the peace helps set the stage for World War II twenty years later.'], 'photo', 'Signing of the treaty in the Hall of Mirrors, Versailles', false);
